package org.praskanth.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/** @param checkoutRef unique id of this checkout (generated by order-service); makes the call idempotent */
public record RedeemRequest(@NotBlank @Size(max = 64) String checkoutRef,
                            @NotBlank @Size(max = 50) String code,
                            @NotEmpty @Valid List<CouponLine> lines) {
}
